final class Parser { private final List<Token> toks; private int pos;
    Token expect(TokenKind k) {
        if (toks.get(pos).kind() != k) throw new ParseException("expected " + k, toks.get(pos).pos());
        return toks.get(pos++);
    }
    Node expr() {                       // one method per grammar rule
        Node left = term();
        while (toks.get(pos).kind() == PLUS || toks.get(pos).kind() == MINUS)  // loop, not left recursion
            left = new Binary(toks.get(pos++).kind(), left, term());
        return left;
    }
}
